def _parameters(kind, scalar):
    # (C type, name, pointer depth, pointed-to constness). Value const is omitted.
    handle = ('sparse_matrix_t', 'A', 0, False)
    if kind == 'create':
        return (('sparse_matrix_t', 'A', 1, False), ('sparse_index_base_t', 'indexing', 0, False),
                ('MKL_INT', 'rows', 0, False), ('MKL_INT', 'cols', 0, False),
                ('MKL_INT', 'starts', 1, False), ('MKL_INT', 'ends', 1, False),
                ('MKL_INT', 'ordinals', 1, False), (scalar, 'values', 1, False))
    if kind == 'export':
        return (handle, ('sparse_index_base_t', 'indexing', 1, False),
                ('MKL_INT', 'rows', 1, False), ('MKL_INT', 'cols', 1, False),
                ('MKL_INT', 'starts', 2, False), ('MKL_INT', 'ends', 2, False),
                ('MKL_INT', 'ordinals', 2, False), (scalar, 'values', 2, False))
    if kind == 'destroy':
        return (handle,)
    common = (('sparse_operation_t', 'operation', 0, False), (scalar, 'alpha', 0, False),
              handle, ('struct matrix_descr', 'descr', 0, False))
    if kind == 'mv':
        return common + ((scalar, 'x', 1, True), (scalar, 'beta', 0, False), (scalar, 'y', 1, False))
    if kind == 'trsv':
        return common + ((scalar,'x',1,True),(scalar,'y',1,False))
    if kind == 'trsm':
        return common + (('sparse_layout_t','layout',0,False),(scalar,'x',1,True),('MKL_INT','columns',0,False),('MKL_INT','ldx',0,False),(scalar,'y',1,False),('MKL_INT','ldy',0,False))
    if kind == 'mm':
        return common + (('sparse_layout_t', 'layout', 0, False), (scalar, 'x', 1, True),
            ('MKL_INT', 'columns', 0, False), ('MKL_INT', 'ldx', 0, False),
            (scalar, 'beta', 0, False), (scalar, 'y', 1, False), ('MKL_INT', 'ldy', 0, False))
    raise ValueError('Unknown Sparse operation')


def descriptions(with_solve=False):
    rows = []
    for scalar, prefix, c_type, zig_type in SCALARS:
        for kind, fmt, recipe in (('create', 'csr', 'createBorrowed'), ('create', 'csc', 'createBorrowed'),
                ('export', 'csr', 'exportBorrowed'), ('export', 'csc', 'exportBorrowed'),
                ('mv', None, 'matrixVectorMultiply'), ('mm', None, 'mm')) + ((('trsv',None,'solveVector'),('trsm',None,'solvePanel')) if with_solve else ()):
            symbol = 'mkl_sparse_' + prefix + '_' + kind + ('_' + fmt if fmt else '')
            rows.append({'symbol': symbol, 'operation': 'sparse.' + kind,
                         'category': 'numerical' if kind in ('mv', 'mm','trsv','trsm') else 'lifecycle',
                         'format': fmt, 'scalar': scalar, 'zig_scalar': zig_type,
                         'parameters': _parameters(kind, c_type), 'return': 'sparse_status_t',
                         'owner': 'sparse-interface-owner', 'recipe': recipe})
    rows.append({'symbol': 'mkl_sparse_destroy', 'operation': 'sparse.destroy', 'category': 'lifecycle',
                 'format': None, 'scalar': None, 'zig_scalar': None, 'parameters': _parameters('destroy', None),
                 'return': 'sparse_status_t', 'owner': 'sparse-interface-owner', 'recipe': 'destroy'})
    return rows


